        g.MapGet("/legal-entities/{entityId:guid}/home", async (Guid entityId, int? page, int? pageSize, HttpContext h, CrmService s, IAuthorizationSubjectStore sub, IPermissionAuthorizer auth, CancellationToken ct) => { var access = await Access(h, sub, auth, "crm.home.read", entityId, ct); return await Execute(h, access, () => s.ListSellerActivitiesAsync(Tenant(h), entityId, ActorOrNull(h), "home", access?.CanViewAll == true, page ?? 1, pageSize ?? 50, ct)); });
        g.MapGet("/legal-entities/{entityId:guid}/worklist", async (Guid entityId, int? page, int? pageSize, HttpContext h, CrmService s, IAuthorizationSubjectStore sub, IPermissionAuthorizer auth, CancellationToken ct) => { var access = await Access(h, sub, auth, "crm.activity.read", entityId, ct); return await Execute(h, access, () => s.ListSellerActivitiesAsync(Tenant(h), entityId, ActorOrNull(h), "worklist", access?.CanViewAll == true, page ?? 1, pageSize ?? 50, ct)); });
        g.MapGet("/legal-entities/{entityId:guid}/attention", async (Guid entityId, int? page, int? pageSize, HttpContext h, CrmService s, IAuthorizationSubjectStore sub, IPermissionAuthorizer auth, CancellationToken ct) => { var access = await Access(h, sub, auth, "crm.activity.read", entityId, ct); return await Execute(h, access, () => s.ListSellerActivitiesAsync(Tenant(h), entityId, ActorOrNull(h), "attention", access?.CanViewAll == true, page ?? 1, pageSize ?? 50, ct)); });
        return app;
    }

    private static async Task<IResult> Execute<T>(HttpContext h, CrmAccess? access, Func<Task<T>> action, int status = 200) { if (access is null) return Results.Unauthorized(); if (!access.Allowed) return Results.Forbid(); try { var value = await action(); return status == 201 ? Results.Created(h.Request.Path, value) : value is null ? Results.NotFound() : Results.Ok(value); } catch (CrmException ex) { var code = ex.Code; var sc = code.Contains("not_found", StringComparison.Ordinal) ? 404 : code.Contains("forbidden", StringComparison.Ordinal) ? 403 : code.Contains("stale", StringComparison.Ordinal) || code.Contains("conflict", StringComparison.Ordinal) || code.Contains("idempotency", StringComparison.Ordinal) ? 409 : 400; return Results.Problem(statusCode: sc, title: code, extensions: new Dictionary<string, object?> { ["code"] = code }); } }
    private static async Task<CrmAccess?> Access(HttpContext h, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, string permission, Guid entity, CancellationToken ct) { if (!Guid.TryParse(h.User.FindFirstValue("tenant_id"), out var tenant) || !Guid.TryParse(h.User.FindFirstValue("membership_id"), out var membership) || !Guid.TryParse(h.User.FindFirstValue(ClaimTypes.NameIdentifier), out var actor)) return null; if (Guid.TryParse(h.User.FindFirstValue("legal_entity_id"), out var bound) && bound != entity) return new(new TenantId(tenant), actor, false, membership, false); var subject = await subjects.LoadAsync(new TenantId(tenant), membership, ct); if (subject is null) return null; var scope = PermissionScope.ForLegalEntity(new TenantId(tenant), new LegalEntityId(entity)); var allowed = authorizer.Authorize(subject, permission, scope); var manager = authorizer.Authorize(subject, "crm.team.manage", scope) || authorizer.Authorize(subject, "crm.pipeline.manage", scope); return new(new TenantId(tenant), actor, allowed, membership, manager); }
    private static TenantId Tenant(HttpContext h) => new(Guid.Parse(h.User.FindFirstValue("tenant_id")!));
    private static Guid Actor(HttpContext h) => Guid.Parse(h.User.FindFirstValue(ClaimTypes.NameIdentifier)!);
    private static Guid? ActorOrNull(HttpContext h) => Guid.TryParse(h.User.FindFirstValue(ClaimTypes.NameIdentifier), out var id) ? id : null;
    private static Guid Membership(HttpContext h) => Guid.Parse(h.User.FindFirstValue("membership_id")!);
    private sealed record CrmAccess(TenantId Tenant, Guid Actor, bool Allowed, Guid MembershipId, bool CanViewAll);
}

